-- Resources content for the Sourcework Notebook tab (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-search',
  p_tool_key => 'transcription',
  p_title => 'Searching across projects and sources',
  p_summary => 'Find a transcript, excerpt or interview by what was said.',
  p_screen_keys => array['sourcework.projects', 'sourcework.project', 'sourcework.source', 'sourcework.sources'],
  p_sort_order => 25,
  p_version_note => 'Search moved into the Notebook tab',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The search box on the "},{"type":"text","text":"Notebook","marks":[{"type":"link","attrs":{"href":"/sourcework?tab=notebook"}}]},{"type":"text","text":" tab of the Sourcework home page searches every project, source, transcript, document and excerpt you can open. Type what you are looking for and press Enter."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Notebook tab"}]},{"type":"paragraph","content":[{"type":"text","text":"The Notebook holds everything you can reuse, in two sections under the search box: "},{"type":"text","text":"Sources","marks":[{"type":"bold"}]},{"type":"text","text":" (every recording and document, whichever project it is in) and "},{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" (every saved clip and passage). Projects stay on their own tab."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How results work"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Results are grouped by project, so several hits from one interview read as one project. The first three show, and "},{"type":"text","text":"Show more","marks":[{"type":"bold"}]},{"type":"text","text":" opens the rest. The words you searched for are highlighted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The chips above the results narrow them by kind: "},{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"In transcripts","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"In documents","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Projects","marks":[{"type":"bold"}]},{"type":"text","text":", each with its count."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Clear search","marks":[{"type":"bold"}]},{"type":"text","text":" to return to the Notebook."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Searching inside a project"}]},{"type":"paragraph","content":[{"type":"text","text":"In a project's "},{"type":"text","text":"Notebook","marks":[{"type":"bold"}]},{"type":"text","text":", the Excerpts section has a search box that covers only that project. To find a word inside one transcript, use "},{"type":"text","text":"Find in this transcript","marks":[{"type":"bold"}]},{"type":"text","text":" above it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The line under the search box says what kind of search is running. Administrators also see whether topic search, which finds a passage by what it is about and not only its exact words, is switched on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Topic search depends on an optional service. When it is off, keyword search still finds everything; it just will not catch a paraphrase."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-15-sourcework-home-notebook',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-15',
  p_title => 'Sourcework: Sources and excerpts share one Notebook tab',
  p_guide_slugs => array['sourcework-search'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Sourcework home now has two tabs for your material: Projects and Notebook. The Notebook brings the Source library and All excerpts together as two sections under one search box, and the search box moved out of the page header into it. On a phone, the projects that need you under Pick up where you left off scroll sideways instead of stacking."}]}]}$body$
);
